package com.lmspilot.identity.security;
import static com.lmspilot.support.security.JwtDecoderConfiguration.hmacKey; import com.nimbusds.jose.jwk.source.ImmutableSecret; import com.nimbusds.jose.proc.SecurityContext; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class IdentitySecurityConfiguration { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(10);} @Bean JwtEncoder jwtEncoder(@Value("${lmspilot.jwt.secret}") String secret){return new NimbusJwtEncoder(new ImmutableSecret<SecurityContext>(hmacKey(secret)));} @Bean SecurityFilterChain identitySecurityFilterChain(HttpSecurity http,org.springframework.core.convert.converter.Converter<org.springframework.security.oauth2.jwt.Jwt,org.springframework.security.authentication.AbstractAuthenticationToken> converter)throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/actuator/info","/api/v1/auth/login","/api/v1/auth/refresh","/api/v1/auth/logout","/internal/v1/**","/error").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter))).build();} }
